  1	import java.awt.*;
  2	import java.awt.event.*;
  3	import javax.swing.*;
  4	import java.util.LinkedHashMap;
  5	import java.util.Map;
  6	
  7	/**
  8	 * A graphical view of the simulation grid.
  9	 * The view displays a colored rectangle for each location 
 10	 * representing its contents. It uses a default background color.
 11	 * Colors for each type of species can be defined using the
 12	 * setColor method.
 13	 *
 14	 * @version 2022.03.01
 15	 */
 16	public class SimulatorView extends JFrame
 17	{
 18	    // Colors used for empty locations.
 19	    private static final Color EMPTY_COLOR = Color.white;
 20	
 21	    // Color used for objects that have no defined color.
 22	    private static final Color UNKNOWN_COLOR = Color.gray;
 23	
 24	    private final String STEP_PREFIX = "Step: ";
 25	    private final String POPULATION_PREFIX = "Population: ";
 26	    private final String DAY_PREFIX = "Number of Days: ";
 27	    private final String INFECTION_PREFIX = "Number of animals infected: ";
 28	    
 29	    private JLabel stepLabel, population, infoLabel, dayLabel;
 30	    
 31	    private JButton stepButton, resetButton, infectionButton;
 32	    
 33	    private FieldView fieldView;
 34	    // A map for storing colors for participants in the simulation
 35	    private Map<Class<?>, Color> colors;
 36	    // A statistics object computing and storing simulation information
 37	    private FieldStats stats;
 38	    
 39	    private int infectedPopulationCount;
 40	    private Simulator simulator;
 41	    private Timer timer;
 42	    /**
 43	     * Create a view of the given width and height.
 44	     * @param height The simulation's height.
 45	     * @param width  The simulation's width.
 46	     */
 47	    public SimulatorView(int height, int width,  Simulator simulator)
 48	    {
 49	        this.simulator =simulator;
 50	        timer = new Timer();
 51	        stats = new FieldStats();
 52	        colors = new LinkedHashMap<>();
 53	
 54	        setTitle("Safari Predator-Prey Simulation");
 55	
 56	        createLabels();
 57	        createButtons();
 58	        JPanel toolBar = new JPanel();
 59	            
 60	        toolBar.add(stepButton);
 61	        toolBar.add(resetButton);
 62	        toolBar.add(infectionButton);
 63	        toolBar.add(population);
 64	
 65	        setLocation(100, 50);
 66	
 67	        fieldView = new FieldView(height, width);
 68	
 69	        Container contents = getContentPane();
 70	
 71	        JPanel infoPane = new JPanel(new BorderLayout());
 72	        infoPane.add(stepLabel, BorderLayout.WEST);
 73	        infoPane.add(infoLabel, BorderLayout.CENTER);
 74	        infoPane.add(dayLabel, BorderLayout.EAST);
 75	        contents.add(infoPane, BorderLayout.NORTH);
 76	        contents.add(fieldView, BorderLayout.CENTER);
 77	        contents.add(toolBar, BorderLayout.SOUTH);
 78	
 79	        pack();
 80	        setVisible(true);
 81	    }
 82	
 83	    /**
 84	     * Called when the 'One Step Button' button is clicked.
 85	     */
 86	    private void nextButton(){
 87	        simulator.simulateOneStep();
 88	    }
 89	
 90	    /**
 91	     * Called when the 'Introduce Infection Button' button is clicked.
 92	     */
 93	    private void infectionButton(){
 94	        simulator.introduceInfection();
 95	    }
 96	
 97	    /**
 98	     * Called when the 'Reset Button' button is clicked.
 99	     */
100	    private void resetButton(){
101	        simulator.reset();
102	    }
103	
104	    /**
105	     * Define a color to be used for a given class of actor.
106	     * @param actorClass The actor's Class object.
107	     * @param color The color to be used for the given class.
108	     */
109	    public void setColor(Class<?> actorClass, Color color)
110	    {
111	        colors.put(actorClass, color);
112	    }
113	
114	    /**
115	     * Display a short information label at the top of the window.
116	     */
117	    public void setInfoText(String text)
118	    {
119	        infoLabel.setText(text);
120	    }
121	
122	    /**
123	     * Create the reset, one step and infection buttons.
124	     * Adds an action to each button.
125	     */
126	    private void createButtons(){
127	        stepButton  = new JButton("One Step ");
128	        resetButton  = new JButton("Reset");
129	        infectionButton  = new JButton("Introduce Infection");
130	        stepButton.addActionListener(new ActionListener() {
131	                public void actionPerformed(ActionEvent e) { nextButton(); }
132	            });
133	        infectionButton.addActionListener(new ActionListener() {
134	                public void actionPerformed(ActionEvent e) { infectionButton(); }
135	            });
136	        resetButton.addActionListener(new ActionListener() {
137	                public void actionPerformed(ActionEvent e) { resetButton(); }
138	            });
139	    }
140	
141	    /**
142	     * Create the different labels to display on the simulation.
143	     */
144	    private void createLabels(){
145	        stepLabel = new JLabel(STEP_PREFIX, JLabel.CENTER);
146	        infoLabel = new JLabel("  ", JLabel.CENTER);
147	        population = new JLabel(POPULATION_PREFIX, JLabel.CENTER);
148	        dayLabel = new JLabel(" ", JLabel.CENTER);
149	    }
150	
151	    /**
152	     * @return The color to be used for a given class of actor.
153	     */
154	    private Color getColor(Class<?> animalClass)
155	    {
156	        Color col = colors.get(animalClass);
157	        if(col == null) {
158	            // no color defined for this class
159	            return UNKNOWN_COLOR;
160	        }
161	        else {
162	            return col;
163	        }
164	    }
165	
166	    /**
167	     * Show the current status of the field.
168	     * @param step Which iteration step it is.
169	     * @param field The field whose status is to be displayed.
170	     */
171	    public void showStatus(Field field)
172	    {
173	        if(!isVisible()) {
174	            setVisible(true);
175	        }
176	
177	        stepLabel.setText(STEP_PREFIX + simulator.getSteps() );
178	        stats.reset();
179	        infectedPopulationCount = 0;
180	
181	        fieldView.preparePaint();
182	
183	        for(int row = 0; row < field.getDepth(); row++) {
184	            for(int col = 0; col < field.getWidth(); col++) {
185	                Object actor = field.getObjectAt(row, col);
186	                if(actor != null) {
187	                    stats.incrementCount(actor, simulator);
188	                    fieldView.drawMark(col, row, getColor(actor.getClass()));
189	                    if(actor instanceof Animal){
190	                        Animal animal = (Animal) actor;
191	                        if (!animal.getHealth()){
192	                            infectedPopulationCount ++;
193	                        }
194	                    }
195	                }
196	                else {
197	                    fieldView.drawMark(col, row, EMPTY_COLOR);
198	                }
199	            }
200	        }
201	        stats.countFinished();
202	        if(simulator.isDay()){
203	            dayLabel.setText( DAY_PREFIX+ simulator.getNoOfDays() + "      Time: " + timer.getTime(simulator.getSteps()) + "   It is Day Time. ");
204	        }else{
205	            dayLabel.setText( DAY_PREFIX+ simulator.getNoOfDays() + "      Time: " + timer.getTime(simulator.getSteps()) + "   It is Night Time ");
206	        }
207	
208	        infoLabel.setText(" " + simulator.getWeather() + "        " + INFECTION_PREFIX + infectedPopulationCount );
209	        population.setText(POPULATION_PREFIX + stats.getPopulationDetails(field, simulator));
210	        fieldView.repaint();
211	    }
212	
213	    /**
214	     * Determine whether the simulation should continue to run.
215	     * @return true If there is more than one species alive.
216	     */
217	    public boolean isViable(Field field)
218	    {
219	        return stats.isViable(field, simulator);
220	    }
221	
222	    /**
223	     * Disable all the buttons.
224	     */
225	    public void disableButton(){
226	        stepButton.setEnabled(false);
227	        infectionButton.setEnabled(false);
228	        resetButton.setEnabled(false);
229	    }
230	
231	    /**
232	     * Enable all the buttons.
233	     */
234	    public void enableButton(){
235	        stepButton.setEnabled(true);
236	        infectionButton.setEnabled(true);
237	        resetButton.setEnabled(true);
238	    }
239	
240	    /**
241	     * Provide a graphical view of a rectangular field. This is 
242	     * a nested class (a class defined inside a class) which
243	     * defines a custom component for the user interface. This
244	     * component displays the field.
245	     * This is rather advanced GUI stuff - you can ignore this 
246	     * for your project if you like.
247	     */
248	    private class FieldView extends JPanel
249	    {
250	        private final int GRID_VIEW_SCALING_FACTOR = 6;
251	
252	        private int gridWidth, gridHeight;
253	        private int xScale, yScale;
254	        Dimension size;
255	        private Graphics g;
256	        private Image fieldImage;
257	
258	        /**
259	         * Create a new FieldView component.
260	         */
261	        public FieldView(int height, int width)
262	        {
263	            gridHeight = height;
264	            gridWidth = width;
265	            size = new Dimension(0, 0);
266	        }
267	
268	        /**
269	         * Tell the GUI manager how big we would like to be.
270	         */
271	        public Dimension getPreferredSize()
272	        {
273	            return new Dimension(gridWidth * GRID_VIEW_SCALING_FACTOR,
274	                gridHeight * GRID_VIEW_SCALING_FACTOR);
275	        }
276	
277	        /**
278	         * Prepare for a new round of painting. Since the component
279	         * may be resized, compute the scaling factor again.
280	         */
281	        public void preparePaint()
282	        {
283	            if(! size.equals(getSize())) {  // if the size has changed...
284	                size = getSize();
285	                fieldImage = fieldView.createImage(size.width, size.height);
286	                g = fieldImage.getGraphics();
287	
288	                xScale = size.width / gridWidth;
289	                if(xScale < 1) {
290	                    xScale = GRID_VIEW_SCALING_FACTOR;
291	                }
292	                yScale = size.height / gridHeight;
293	                if(yScale < 1) {
294	                    yScale = GRID_VIEW_SCALING_FACTOR;
295	                }
296	            }
297	        }
298	
299	        /**
300	         * Paint on grid location on this field in a given color.
301	         */
302	        public void drawMark(int x, int y, Color color)
303	        {
304	            g.setColor(color);
305	            g.fillRect(x * xScale, y * yScale, xScale-1, yScale-1);
306	        }
307	
308	        /**
309	         * The field view component needs to be redisplayed. Copy the
310	         * internal image to screen.
311	         */
312	        public void paintComponent(Graphics g)
313	        {
314	            if(fieldImage != null) {
315	                Dimension currentSize = getSize();
316	                if(size.equals(currentSize)) {
317	                    g.drawImage(fieldImage, 0, 0, null);
318	                }
319	                else {
320	                    // Rescale the previous image.
321	                    g.drawImage(fieldImage, 0, 0, currentSize.width, currentSize.height, null);
322	                }
323	            }
324	        }
325	    }
326	}
